  'p2p.or': { he: 'או הצטרף לחבר', en: 'or join a friend', ru: 'или присоединитесь к другу', ar: 'أو انضم إلى صديق' },
  'p2p.opening': { he: 'פותח חדר…', en: 'Opening a room…', ru: 'Открываем комнату…', ar: 'جارٍ فتح الغرفة…' },
  'p2p.joining': { he: 'מתחבר לחבר…', en: 'Connecting to your friend…', ru: 'Подключаемся к другу…', ar: 'جارٍ الاتصال بصديقك…' },
  'p2p.notFound': { he: 'לא נמצא חדר עם הקוד הזה. בדוק את הקוד, וודא שהחבר עדיין בחדר.', en: 'No room with that code. Check the code and make sure your friend is still in the room.', ru: 'Комната с таким кодом не найдена. Проверьте код и что друг ещё в комнате.', ar: 'لا توجد غرفة بهذا الرمز. تحقق من الرمز ومن أن صديقك ما زال في الغرفة.' },
  'p2p.timeout': { he: 'החיבור לחבר לא הצליח (ייתכן שהרשת חוסמת חיבור ישיר). נסו רשת אחרת, למשל נתונים סלולריים.', en: 'Could not connect to your friend (the network may block direct connections). Try another network, such as mobile data.', ru: 'Не удалось подключиться к другу (сеть может блокировать прямые соединения). Попробуйте другую сеть, например мобильный интернет.', ar: 'تعذّر الاتصال بصديقك (قد تمنع الشبكة الاتصال المباشر). جرّب شبكة أخرى مثل بيانات الجوال.' },
